                        const labels = [...copyColoring.slice(2, 6), 'Ursinho Amigão', 'Gatinho Tito', 'Girafinha Gina', 'Coelhinha Lili', copyColoring[6]];
                        const drawings = [["Turma-Colorida.jpg","./colorir/Turma-Colorida.jpg"],["Turma-Para-Colorir.png","./colorir/Turma-Para-Colorir.png"],["Ursinho-Ferias.jpg","./colorir/Ursinho-Ferias.jpg"],["Ferias-Para-Colorir.png","./colorir/Ferias-Para-Colorir.png"],["Ursinho-Lado-a-Lado.png","./colorir/Ursinho-Lado-a-Lado.png"],["Tito-Lado-a-Lado.png","./colorir/Tito-Lado-a-Lado.png"],["Gina-Lado-a-Lado.png","./colorir/Gina-Lado-a-Lado.png"],["Lili-Lado-a-Lado.png","./colorir/Lili-Lado-a-Lado.png"],["Cartilha-Ursinho-Para-Colorir.zip","./colorir/Cartilha-Ursinho-Para-Colorir.zip"]];
                        drawings[2] = [vacationFile, './colorir/' + vacationFile];
