                        description.textContent = copy[1];
                        const seal = document.createElement('div');
                        seal.className = 'diploma-seal';
                        seal.setAttribute('aria-hidden', 'true');
                        seal.innerHTML = '<svg viewBox="0 0 96 66" width="76" height="53" aria-hidden="true"><path d="M36 31 22 62l14-5 8 7 6-28m10-5 14 31-14-5-8 7-6-28" fill="#203b67" stroke="#d99f38" stroke-width="2"/><path d="M44 17C30 8 13 2 9 13c-4 9 0 23 7 25 8 2 23-4 29-9m7-12C66 8 83 2 87 13c4 9 0 23-7 25-8 2-23-4-29-9" fill="#efbd58" stroke="#9b621e" stroke-width="2"/><path d="M16 17q8-4 26 5M80 17q-8-4-26 5" fill="none" stroke="#ffe7a1" stroke-width="3" stroke-linecap="round"/><rect x="40" y="15" width="16" height="19" rx="5" fill="#ffdc7f" stroke="#9b621e" stroke-width="2"/></svg>';
                        const diplomaPortrait = portrait.cloneNode();
                        diplomaPortrait.className = 'diploma-portrait';
                        diploma.append(diplomaPortrait, diplomaTitle, recipient, description, certificate, playerCredit, seal);
