            handleContinue: function(choice) {
                clearInterval(this.continueCountdownInterval);
                const continueModalElement = document.getElementById('continueModal');
                if (continueModalElement) {
                    continueModalElement.style.display = 'none';
                }

                if (choice === 'sim') {
                    console.log("DEBUG: Jogador escolheu SIM. Reiniciando para seleção de personagem.");
                    this.vidas = 3;
                    const personagemSelecaoElement = document.getElementById('personagemSelecao');
                    if (personagemSelecaoElement) {
                        personagemSelecaoElement.style.display = 'flex';
                    }
                    if (this.ctx && this.canvas) this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
                    this.totalAllItemsCollected = 0;
                    this.tempo = 100 - 10 * (this.series ?? 1);

                    this.itens = [];
                    this.obstaculos = [];
                    this.chest = null;
                    this.currentPhase = 1;
                    this.objectiveCounts = {};
                    const introScreenElement = document.getElementById('introScreen');
                    if (introScreenElement) {
                        updateProgressControls();
                        introScreenElement.style.display = 'flex';
                    }
                    const hudElement = document.getElementById('hud');
                    if (hudElement) {
                        hudElement.style.display = 'none';
                    }
                } else {
                    console.log("DEBUG: Jogador escolheu NÃO ou tempo esgotou. Recarrega a página.");
                    location.reload();
                }
            },

            animar: function(currentTime) {
                this.animationFrame = requestAnimationFrame(this.animar.bind(this));

                if (this.paused || this.orientationBlocked || document.hidden || this.backgrounded) return;

                if (!this.lastFrameTime) {
                    this.lastFrameTime = currentTime;
                }

                const elapsed = currentTime - this.lastFrameTime;
                this.frameInterval = 1000 / this.targetFPS;

                if (elapsed > this.frameInterval) {
                    this.lastFrameTime = currentTime - (elapsed % this.frameInterval);

                    let winConditionMet = false;
                    const phaseData = phasesData[this.currentPhase];
                    if (phaseData && phaseData.chest) {
                        winConditionMet = (this.chest && this.chest.isOpened);
                    } else if (phaseData) {
                        winConditionMet = phaseData.items.filter(item => item.isObjective).every(item => {
                            return (this.objectiveCounts[item.type] || 0) >= item.count;
                        });
                    }

                    if (this.vidas <= 0 || this.tempo <= 0 || winConditionMet) {
                        return;
                    }

                    if (this.ctx && this.canvas) {
                        const {clientWidth, clientHeight, width, height} = this.canvas;
                        this.canvasAspect = clientWidth && clientHeight ? (clientWidth / width) / (clientHeight / height) : 1;
                        const fitKey = [clientWidth,clientHeight,width,height,document.body.classList.contains('large-sprites')].join(':');
                        if (fitKey !== this.boardFitKey) this.fitObjectsToCanvas();
                        this.ctx.clearRect(0, 0, width, height);
                    } else {
                        console.error("Erro: Canvas ou contexto 2D não está disponível para limpeza.");
                        return;
                    }


                    const prevX = this.player.x;
                    const prevY = this.player.y;

                    if (this.teclas["w"]) this.player.y -= this.PLAYER_SPEED;
                    if (this.teclas["s"]) this.player.y += this.PLAYER_SPEED;
                    if (this.teclas["a"]) this.player.x -= this.PLAYER_SPEED;
                    if (this.teclas["d"]) this.player.x += this.PLAYER_SPEED;

                    if (this.touchTarget) {
                        const dx = this.touchTarget.x - this.player.x - this.player.width / 2;
                        const dy = this.touchTarget.y - this.player.y - this.player.height / 2;
                        const distance = Math.hypot(dx, dy);
                        const fraction = Math.min(1, this.PLAYER_SPEED / (distance || 1));
                        this.player.x += dx * fraction;
                        this.player.y += dy * fraction;
                    }

                    this.keepInsideBoard(this.player, true);

                    const nextY = this.player.y;
                    const blocked = () => this.obstaculos.some(obstacle =>
                        obstacle.isObstacle && this.checkCollision(this.player, obstacle));
                    this.player.y = prevY;
                    if (blocked()) this.player.x = prevX;
                    this.player.y = nextY;
                    if (blocked()) this.player.y = prevY;

                    if (!this.guided) this.handleInteractions();

                    if (this.chest && this.currentPhase === 1) {
                        this.drawItem(this.chest);
                    }
                    this.itens.forEach(this.drawItem.bind(this));
                    this.obstaculos.forEach(this.drawItem.bind(this));
                    this.drawPlayer();
                    this.collectionEffects = this.collectionEffects.filter(effect => effect.until > currentTime);
                    for (const effect of document.body.classList.contains('reduce-effects') ? [] : this.collectionEffects) {
                        const remaining = (effect.until - currentTime) / 360;
                        this.ctx.save();
                        this.ctx.globalAlpha = Math.min(1, remaining);
                        this.ctx.strokeStyle = '#fff1a3';
                        this.ctx.lineWidth = 3;
                        this.ctx.beginPath();
                        this.ctx.arc(effect.x, effect.y, 12 + (1 - remaining) * 23, 0, 2 * Math.PI);
                        this.ctx.stroke();
                        this.ctx.restore();
                    }
                    if (this.currentPhase === 1) {
                        this.hasMoved ||= this.player.x !== prevX || this.player.y !== prevY;
                        const nearChest = this.chest && !this.chest.isOpened &&
                            Math.hypot(this.player.x - this.chest.x, this.player.y - this.chest.y) < this.CHEST_SIZE * 1.4;
                        const hint = document.getElementById('tutorialHint');
                        const message = this.guided ? '' : !this.hasMoved ? t('moveHelp') : nearChest ? t(this.isReadyForChest() ? 'openHelp' : 'need') : '';
                        if (hint.textContent !== message) hint.textContent = message;
                    }
                }
            },

